const require_defaults = require("../utils/defaults.js");
const require_domTarget = require("../utils/domTarget.js");
const require_useStableTarget = require("../utils/useStableTarget.js");
const require_index = require("../useEventListener/index.js");
let react = require("react");
//#region src/useMousePressed/index.ts
const listenerOptions = { passive: true };
const useMousePressed = (target, options = require_defaults.defaultOptions) => {
	const { touch = true, drag = true, initialValue = false } = options;
	const [pressed, setPressed] = (0, react.useState)(initialValue);
	const [sourceType, setSourceType] = (0, react.useState)(null);
	const { key: elementKey, ref: elementRef } = require_useStableTarget.useStableTarget(target);
	const onMousePressed = (0, react.useCallback)(() => {
		setPressed(true);
		setSourceType("mouse");
	}, []);
	const onTouchPressed = (0, react.useCallback)(() => {
		setPressed(true);
		setSourceType("touch");
	}, []);
	const onReleased = (0, react.useCallback)(() => {
		setPressed(false);
		setSourceType(null);
	}, []);
	require_index.useEventListener("mousedown", onMousePressed, target, listenerOptions);
	require_index.useEventListener("mouseleave", onReleased, () => window, listenerOptions);
	require_index.useEventListener("mouseup", onReleased, () => window, listenerOptions);
	(0, react.useEffect)(() => {
		const element = require_domTarget.getTargetElement(elementRef.current);
		if (!element) return;
		if (drag) {
			element.addEventListener("dragstart", onMousePressed, listenerOptions);
			element.addEventListener("drop", onReleased, listenerOptions);
			element.addEventListener("dragend", onReleased, listenerOptions);
		}
		if (touch) {
			element.addEventListener("touchstart", onTouchPressed, listenerOptions);
			element.addEventListener("touchend", onReleased, listenerOptions);
			element.addEventListener("touchcancel", onReleased, listenerOptions);
		}
		return () => {
			if (drag) {
				element.removeEventListener("dragstart", onMousePressed);
				element.removeEventListener("drop", onReleased);
				element.removeEventListener("dragend", onReleased);
			}
			if (touch) {
				element.removeEventListener("touchstart", onTouchPressed);
				element.removeEventListener("touchend", onReleased);
				element.removeEventListener("touchcancel", onReleased);
			}
		};
	}, [
		drag,
		touch,
		elementKey,
		elementRef,
		onMousePressed,
		onTouchPressed,
		onReleased
	]);
	return [pressed, sourceType];
};
//#endregion
exports.useMousePressed = useMousePressed;
